        "c7f379d140224ca18d7211d4eb384ce6": {
          "id": "c7f379d140224ca18d7211d4eb384ce6",
          "name": "Assign Value To Hotel Variable ",
          "script": "(function execute() {\n    var details = inputs.hotel_details || '';\n\n// Split using comma\nvar parts = details.split(',');\n\n// Remove extra spaces from each value\nfor (var i = 0; i < parts.length; i++) {\n    parts[i] = parts[i].trim();\n}\n\n// Assign values\noutputs.hotel_name = parts.length > 0 ? parts[0] : '';\noutputs.hotel_city = parts.length > 1 ? parts[1] : '';\noutputs.hotel_state = parts.length > 2 ? parts[2] : '';\noutputs.hotel_country = parts.length > 3 ? parts[3] : '';\n})()\n",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
        "ca430a669ab04feeb222f04e82bbfeed": {
          "id": "ca430a669ab04feeb222f04e82bbfeed",
